function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function cleanProfile(x){if(!x||typeof x.name!=='string'||!x.name.trim()||x.name.length>60||typeof x.city!=='string'||!x.city.trim()||x.city.length>60||!Number.isInteger(Number(x.buffer))||Number(x.buffer)<0||Number(x.buffer)>30)throw Error('Некорректные настройки заведения.');return {name:x.name.trim(),city:x.city.trim(),buffer:Number(x.buffer)};}
let profile;try{profile=cleanProfile(readStore('qor-profile',null));}catch{profile={name:'Моё заведение',city:'Тараз',buffer:10};}
function cleanHistory(list){if(!Array.isArray(list)||list.length>120)throw Error('Некорректная история планов.');return list.map(p=>{if(!p||typeof p.id!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(p.date)||!['planned','done'].includes(p.status)||!Array.isArray(p.items)||!p.items.length||p.items.length>100||typeof p.created!=='string'||!Number.isFinite(Date.parse(p.created)))throw Error('Некорректный сохранённый план.');return {id:p.id.slice(0,80),date:p.date,status:p.status,created:p.created,demo:!!p.demo,items:p.items.map(i=>{if(typeof i.product!=='string'||!i.product.length||i.product.length>100||/^[=+@\-]/.test(i.product)||!Number.isInteger(i.qty)||i.qty<0||i.qty>1e10)throw Error('Некорректная позиция плана.');return {product:i.product,qty:i.qty};})};});}
let history;try{history=cleanHistory(readStore('qor-history',[]));}catch{history=[];}
function applyProfile(){ $('#workspace-name').textContent=profile.name;$('#workspace-city').textContent=profile.city+' · рабочее пространство';$('#business-name').value=profile.name;$('#business-city').value=profile.city;$('#default-buffer').value=profile.buffer;$('#buffer').value=profile.buffer;render();}
applyProfile();
$('#settings-form').onsubmit=e=>{e.preventDefault();try{const next=cleanProfile({name:$('#business-name').value,city:$('#business-city').value,buffer:Number($('#default-buffer').value)});localStorage.setItem('qor-profile',JSON.stringify(next));profile=next;applyProfile();notify('Настройки сохранены.');}catch(err){notify('Не удалось сохранить: '+err.message);}};
function confirmAction(title,description,action){$('#confirm-title').textContent=title;$('#confirm-description').textContent=description;$('#confirm-dialog').showModal();$('#confirm-no').onclick=()=>$('#confirm-dialog').close();$('#confirm-yes').onclick=()=>{$('#confirm-dialog').close();action();};}
$('#approve').onclick=()=>{const plan={id:globalThis.crypto?.randomUUID?.()||String(Date.now()),date:$('#plan-date').value,created:new Date().toISOString(),status:'planned',demo:isDemo,items:plans.map(p=>({product:p.name,qty:p.qty}))};const next=[plan,...history].slice(0,120);try{localStorage.setItem('qor-history',JSON.stringify(next));history=next;$('#saved-plan').textContent=`План на ${plan.date} добавлен в историю. ${plan.items.length} позиций.`;renderHistory();notify('План сохранён. Вы найдёте его в истории планов.');}catch{notify('Не удалось сохранить. Скачайте план CSV.');}};
function renderHistory(){if(!history.length){$('#history-list').innerHTML='<article class="card empty-state"><div class="upload-icon">◷</div><h2>Первый план ещё впереди</h2><p>Составьте и сохраните план приготовления. Здесь появятся ваши задания для кухни.</p><button class="primary" id="history-start">Составить план →</button></article>';$('#history-start').onclick=()=>go('plan');return;}$('#history-list').innerHTML=history.map((p,i)=>`<article class="card history-card"><div class="card-top"><div><span class="eyebrow">${p.demo?'ПРИМЕР · ':''}ПЛАН ПРИГОТОВЛЕНИЯ</span><h2>${esc(new Date(p.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}))}</h2><p>Сохранён ${esc(new Date(p.created).toLocaleString('ru-RU'))} · ${p.items.length} позиций</p></div><span class="tag ${p.status==='done'?'':'muted'}">${p.status==='done'?'Выполнен':'Запланирован'}</span></div><div class="history-items">${p.items.map(x=>`<span>${esc(x.product)} <b>${x.qty} шт.</b></span>`).join('')}</div><div class="history-actions"><button class="outline" data-history="export" data-index="${i}">↓ Скачать CSV</button><button class="outline" data-history="status" data-index="${i}">${p.status==='done'?'Вернуть в работу':'✓ Отметить выполненным'}</button><button class="text-button danger" data-history="delete" data-index="${i}">Удалить</button></div></article>`).join('');document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.index),p=history[i];if(b.dataset.history==='export'){download('qor-plan-'+p.date+'.csv',[['date','product','prepare'],...p.items.map(x=>[p.date,x.product,x.qty])]);return;}const mutate=()=>{const next=history.map(x=>({...x}));if(b.dataset.history==='delete')next.splice(i,1);else next[i].status=p.status==='done'?'planned':'done';try{localStorage.setItem('qor-history',JSON.stringify(next));history=next;renderHistory();}catch{notify('Не удалось сохранить изменение.');}};if(b.dataset.history==='delete')confirmAction('Удалить этот план?','План исчезнет из истории на этом устройстве. Продажи сохранятся.',mutate);else mutate();});}
$('#reset').onclick=()=>confirmAction('Открыть пример данных?','Текущая история продаж будет заменена примером. Если она нужна, сначала скачайте резервную копию в настройках. Сохранённые планы останутся.',()=>{try{localStorage.removeItem('qor-data');data=QorModel.demo();isDemo=true;init();notify('Пример данных открыт.');}catch{notify('Браузер не разрешил изменить данные.');}});
$('#print-plan').onclick=()=>{$('#print-date').textContent=profile.name+' · '+$('#plan-date').value+(isDemo?' · Пример данных':'');document.body.classList.add('printing-plan');window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('printing-plan'));
$('#backup').onclick=()=>{const contents=JSON.stringify({version:1,created:new Date().toISOString(),profile,history,data:isDemo?null:data},null,2),url=URL.createObjectURL(new Blob([contents],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='qor-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Резервная копия подготовлена.');};
$('#restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('Максимальный размер — 8 МБ.');const raw=JSON.parse(await file.text());if(raw.version!==1)throw Error('Неподдерживаемый формат копии.');const p=cleanProfile(raw.profile),h=cleanHistory(raw.history),d=raw.data===null?null:validate(raw.data);confirmAction('Восстановить рабочее пространство?','Копия заменит текущие продажи, настройки и историю планов на этом устройстве.',()=>{const keys=['qor-profile','qor-history','qor-data'],old=keys.map(k=>localStorage.getItem(k));try{localStorage.setItem(keys[0],JSON.stringify(p));localStorage.setItem(keys[1],JSON.stringify(h));if(d)localStorage.setItem(keys[2],JSON.stringify(d));else localStorage.removeItem(keys[2]);profile=p;history=h;data=d||QorModel.demo();isDemo=!d;init();applyProfile();renderHistory();$('#restore-error').textContent='';notify('Рабочее пространство восстановлено.');}catch{keys.forEach((k,i)=>{try{if(old[i]===null)localStorage.removeItem(k);else localStorage.setItem(k,old[i]);}catch{}});$('#restore-error').textContent='Не удалось восстановить копию: недостаточно места или сохранение запрещено.';}});}catch(err){$('#restore-error').textContent=err.message;}e.target.value='';};
if(readStore('qor-welcomed',false))$('#welcome').hidden=true;$('#dismiss-welcome').onclick=()=>{$('#welcome').hidden=true;try{localStorage.setItem('qor-welcomed','true');}catch{}};
const pages=['overview','plan','data','history','settings','help'];function route(){const page=location.hash.slice(1);if(pages.includes(page))go(page);}window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(pages.includes(page)&&!$('#'+page).classList.contains('active'))go(page);});renderHistory();route();
